CREATE TABLE IF NOT EXISTS accounts (id bigserial primary key, account_number varchar(20) not null unique, customer_number varchar(20) not null, account_type varchar(30) not null, status varchar(20) not null, currency varchar(3) not null, balance numeric(19,4) not null, available_balance numeric(19,4) not null, created_at timestamp not null, updated_at timestamp not null, version bigint not null default 0);
